package app.thousandwords.scan;
import app.thousandwords.user.UserRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ScanService { private final UserRepository users; private final GroceryScanRepository scans; private final VisionProvider vision; public ScanService(UserRepository u,GroceryScanRepository s,VisionProvider v){users=u;scans=s;vision=v;} @Transactional public ScanResponse create(UUID userId,byte[] data,String type){var products=vision.recognize(data,type);var scan=new GroceryScan(users.getReferenceById(userId),vision.demoMode());scan.summary=products.stream().map(VisionProduct::name).limit(3).reduce((a,b)->a+", "+b).orElse("Package scan");products.forEach(p->scan.products.add(new RecognizedProduct(scan,p)));scans.save(scan);return response(scan);} @Transactional(readOnly=true) public List<HistoryItem> history(UUID userId){return scans.findByUserIdOrderByCreatedAtDesc(userId).stream().map(x->new HistoryItem(x.id,x.summary,x.createdAt)).toList();} private ScanResponse response(GroceryScan s){return new ScanResponse(s.id,s.demoMode,s.products.stream().map(p->new ProductDto(p.id,p.brand,p.name,p.variant,p.size,p.confidence,p.upc,p.price)).toList());} public record ProductDto(UUID id,String brand,String name,String variant,String size,double confidence,String upc,java.math.BigDecimal price){} public record ScanResponse(UUID scanId,boolean demoMode,List<ProductDto> products){} public record HistoryItem(UUID id,String summary,java.time.Instant createdAt){} }
